 static void MigrateTasks(string password){dynamic scheduler=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service",true));scheduler.Connect();dynamic folder=scheduler.GetFolder("\\");try{foreach(string name in new[]{"AccessPolicy","Certificate Revocation Refresh","Test SMTP","DailyArchive","Notifications","Registration"}){dynamic task=folder.GetTask("AGORA-OUT "+name);dynamic definition=task.Definition;string backup=@"C:\AGORA-OUT\csharp-runtime\task-"+name+".xml";if(!File.Exists(backup))File.WriteAllText(backup,(string)task.Xml);string mode=name=="AccessPolicy"?"access":name=="Certificate Revocation Refresh"?"crl":name=="Test SMTP"?"smtp":name=="DailyArchive"?"archive":name=="Notifications"?"notifications":"registration";definition.Actions.Clear();dynamic action=definition.Actions.Create(0);action.Path=@"C:\AGORA-OUT\csharp-runtime\Agora.Outgoing.Runner.exe";action.Arguments=mode;action.WorkingDirectory=@"C:\AGORA-OUT\csharp-runtime";int logon=(int)definition.Principal.LogonType;dynamic registered=folder.RegisterTaskDefinition((string)task.Name,definition,4,(string)definition.Principal.UserId,logon==1?password:null,logon,null);if(name=="Test SMTP"){if((int)task.State==4)task.Stop(0);registered.Run(null);}}}
